/** Deterministic, detailed toolpaths for preview-only performance/correctness checks. */
export function detailedGcode({ layers = 120, segments = 1024, tools = 1, config = {} } = {}) {
  if (Object.keys(config).length < 80) throw new Error('Use a complete Orca configuration for this fixture');
  if (![layers, segments, tools].every(Number.isInteger) || layers < 1 || segments < 16 || tools < 1 || tools > 4) throw new Error('Invalid fixture size');
  const lines = [
    '; HEADER_BLOCK_START', '; generated by OrcaSlicer 2.5.0-dev',
    `; total layer number: ${layers}`, '; filament_density: 1.24', '; filament_diameter: 1.75',
    '; HEADER_BLOCK_END', 'G21', 'G90', 'M83', 'M104 S210', 'M106 S128', 'M204 S2000', 'T0'
  ];
  for (let layer = 0; layer < layers; layer++) {
    const z = (layer + 1) * 0.2;
    lines.push(';LAYER_CHANGE', `;Z:${z.toFixed(2)}`, ';HEIGHT:0.2', `G1 Z${z.toFixed(2)} F3000`, `T${layer % tools}`, ';TYPE:Outer wall', ';WIDTH:0.45');
    let previousX = 0, previousY = 0;
    for (let move = 0; move <= segments; move++) {
      const angle = move / segments * Math.PI * 2;
      const radius = 65 + 8 * Math.sin(angle * 17 + layer * 0.03) + 5 * Math.cos(angle * 7);
      const x = 150 + radius * Math.cos(angle), y = 150 + radius * Math.sin(angle);
      if (move === 0) lines.push(`G1 X${x.toFixed(4)} Y${y.toFixed(4)} F18000`);
      else {
        const extrusion = Math.hypot(x - previousX, y - previousY) * 0.0374;
        const feed = 1200 + (move % 13) * 600;
        lines.push(`G1 X${x.toFixed(4)} Y${y.toFixed(4)} E${extrusion.toFixed(6)} F${feed}`);
      }
      previousX = x; previousY = y;
    }
  }
  const fixtureConfig = { ...config,
    filament_colour: ['#0088FF', '#FF3300', '#FFD000', '#22CC66'].slice(0, tools).join(';'),
    filament_diameter: Array(tools).fill('1.75').join(','),
    filament_density: Array(tools).fill('1.24').join(',') };
  lines.push('; CONFIG_BLOCK_START', ...Object.entries(fixtureConfig).map(([key, value]) => `; ${key} = ${value}`),
    '; CONFIG_BLOCK_END', '');
  return lines.join('\n');
}
